/* eslint-disable @typescript-eslint/no-require-imports */
const assert=require('node:assert/strict'),fixture=require('./life-loop.cjs');
const owner=w=>w.characters.find(c=>c.id==='owner');
module.exports=async function runLifeLoop(s,habitViews,checkpoint=async()=>{}){
  const start=await s.read();let w=await s.advance();const firstTrials=structuredClone(w.freeTrials);assert.equal(Object.keys(firstTrials).length,1);assert.equal(Object.values(firstTrials)[0].roll,14);const selected=structuredClone(owner(w).plan.selectedResult);assert.equal(w.objects.find(o=>o.id==='material').lifecycle,'consumed');assert.equal(w.objects.find(o=>o.id==='workpiece').state.progress,'prepared');assert.equal(owner(w).plan.phases.cursor,1);
  s.transport.choose(input=>{assert.ok(input.self.bodyFeelings.some(f=>f.feeling.includes('餓')));return fixture.choose('pause');});w=await s.advance();assert.equal(owner(w).pausedActivity.elapsedMinutes,30);assert.equal(owner(w).plan,undefined);await checkpoint('paused',w);
  s.transport.choose(fixture.ingest);w=await s.advance();assert.equal(owner(w).needs.values.hunger,16.25);assert.equal(owner(w).needs.values.thirst,18.5);assert.ok(w.objects.filter(o=>['meal','water'].includes(o.id)).every(o=>o.lifecycle==='consumed'));await checkpoint('ingested',w);
  s.transport.choose(fixture.rest(120));w=await s.advance();const firstRest=owner(w).needs.values.fatigue;const restCalls=s.transport.counts();s.transport.choose(fixture.choose('continue'));for(const minutes of [30,30,30,15])w=await s.advance(minutes);assert.equal(owner(w).plan,undefined);assert.equal(owner(w).needs.values.fatigue,firstRest-14);assert.equal(owner(w).pausedActivity.elapsedMinutes,30);assert.equal(s.transport.counts().adjudication,restCalls.adjudication);assert.ok(s.transport.counts().npc<=restCalls.npc+1);
  s.transport.choose(input=>fixture.choose('resume',{target:input.self.pausedActivity.id}));w=await s.advance();assert.equal(owner(w).pausedActivity,undefined);assert.equal(owner(w).plan.phases.cursor,1);assert.deepEqual(owner(w).plan.selectedResult,selected);assert.deepEqual(w.freeTrials,firstTrials);await checkpoint('resumed',w);const originalMaterialRevision=w.objects.find(o=>o.id==='material').revision;
  s.transport.choose(fixture.choose('continue'));for(let i=0;i<7;i++)w=await s.advance(30);assert.equal(owner(w).plan,undefined);assert.equal(w.objects.find(o=>o.id==='workpiece').state.progress,'finished');assert.equal(w.objects.find(o=>o.id==='material').revision,originalMaterialRevision);assert.equal(s.transport.counts().adjudication,2);
  s.transport.choose(fixture.sleep);w=await s.advance();const sleepingCalls=s.transport.counts(),sleepStart=w.minute-15;assert.equal(owner(w).plan.bodyActivity.kind,'sleep');let maxSleep=15;
  s.transport.choose(fixture.reflect(15));while(owner(w).plan?.bodyActivity?.kind==='sleep'){w=await s.advance(30);maxSleep=w.minute-sleepStart;if(maxSleep===105)await checkpoint('sleeping',w);if(owner(w).plan?.bodyActivity?.kind==='sleep')assert.deepEqual(s.transport.counts(),sleepingCalls);assert.ok(maxSleep<600);}
  assert.ok(maxSleep>90);assert.ok(w.events.some(e=>e.text.includes('自然醒')));assert.ok(owner(w).needs.values.sleep<=22);await checkpoint('woke',w);
  let firstTidy;
  for(let day=0;day<3;day++){
   s.transport.choose(fixture.choose('work',{target:'tidy',content:'整理桌面'}));w=await s.advance();if(day===0)firstTidy=w.minute;const trigger=owner(w).habitEvidence.at(-1).memory;assert.ok(trigger);
   s.transport.choose(fixture.rest(15));w=await s.advance();const action=owner(w).habitEvidence.at(-1).memory;
   s.transport.choose(()=>({...fixture.reflect(15),habitCandidates:[{trigger,action}],...(day===0?{preferenceUpdates:[{operation:'upsert',id:'after-work-rest',version:0,topic:'短暫休息',context:'完成整理之後',text:'我喜歡完成整理後坐一會兒。',references:[{kind:'short',...action}],reason:'剛才實際休息的感受令我想保留這個偏愛。'}]}:{})}));w=await s.advance();assert.equal(owner(w).eventHabits[0].observedDays.length,day+1);await checkpoint(`day-${day+1}`,w);
   if(day<2){const nextTidy=firstTidy+(day+1)*1440;const duration=nextTidy-w.minute-15;s.transport.choose(fixture.reflect(duration));w=await s.advance();s.transport.choose(fixture.choose('continue'));while(w.minute<nextTidy-15)w=await s.advance(Math.min(30,nextTidy-15-w.minute));assert.equal(w.minute,nextTidy-15);}
  }
  assert.equal(habitViews.eventHabitViews(w,owner(w))[0].established,true);assert.equal(owner(w).preferences.items[0].id,'after-work-rest');assert.ok(habitViews.habitViews(w,owner(w)).some(h=>h.type==='work'&&h.target==='tidy'&&h.established));
  s.transport.choose(input=>{assert.ok(input.learnedHabits.some(h=>h.tendency.includes('之後')));assert.equal(input.self.preferences.items[0].id,'after-work-rest');return fixture.reflect(15);});w=await s.advance();assert.ok(w.minute-start.minute>2880);assert.ok(s.transport.counts().npc<80);assert.equal(s.transport.counts().adjudication,3);assert.deepEqual(w.freeTrials,firstTrials);assert.deepEqual((await s.read()).characters,w.characters);
  await checkpoint('complete',w);return {world:w,counts:s.transport.counts(),elapsedMinutes:w.minute-start.minute};
};
